CREATE POLICY "read product images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id IN ('product-images','atendentes-v1-private'));
CREATE POLICY "staff upload images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id IN ('product-images','atendentes-v1-private') AND public.is_staff(auth.uid()));
CREATE POLICY "staff update images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id IN ('product-images','atendentes-v1-private') AND public.is_staff(auth.uid()));
CREATE POLICY "staff delete images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id IN ('product-images','atendentes-v1-private') AND public.is_staff(auth.uid()));